use vstd::prelude::*;

verus! {

fn split_and_append(list: &Vec<i32>, n: usize) -> (new_list: Vec<i32>)
    requires
        list.len() > 0,
        0 < n,
        n < list.len(),
    ensures
        new_list.len() == list.len(),

        forall|i: int|
            0 <= i && i < (list.len() as int - n as int) ==>
                new_list[i] == list[i + n as int],
        forall|i: int|
            (list.len() as int - n as int) <= i && i < list.len() as int ==>
                new_list[i] == list[i - (list.len() as int - n as int)],

        forall|i: int|
            0 <= i && i < list.len() as int ==>
                new_list[i] == list[((i + n as int) % (list.len() as int))],
{
    let len = list.len();
    let mut out: Vec<i32> = Vec::new();

    let mut i: usize = 0;
    while i < len
        invariant
            len == list.len(),
            out.len() == i,
            i <= len,
            forall|j: int|
                0 <= j && j < i as int ==>
                    out[j] == list[((j + n as int) % (len as int))],
    {
        let idx = (i + n) % len;
        out.push(list[idx]);
        i += 1;
    }

    out
}

} // verus!